static/css/date-picker.css.content:
/* Date input enhancements */
.date-input-wrapper {
    position: relative;
}

.date-quick-buttons {
    z-index: 10;
    pointer-events: none;
}

.date-quick-buttons button {
    pointer-events: auto;
    font-size: 0.75rem;
    padding: 0.25rem 0.5rem;
}

.calendar-grid-container {
    max-height: 300px;
    overflow-y: auto;
}

.calendar-day {
    cursor: pointer;
    padding: 8px 4px;
    border: 1px solid transparent;
    transition: all 0.2s ease;
}

.calendar-day.current-month:hover {
    background-color: #e9ecef;
    border-color: #007bff;
}

.calendar-day.today {
    background-color: #007bff;
    color: white;
    font-weight: bold;
}

.calendar-day.other-month {
    color: #6c757d;
    cursor: default;
}

.quick-dates {
    border-bottom: 1px solid #dee2e6;
    padding-bottom: 10px;
    margin-bottom: 10px;
}

/* Auto-select indicators */
.auto-date-selected {
    background-color: #e8f4fd;
    border-color: #007bff;
}

/* Modal enhancements for date picker */
#datePickerModal .modal-body {
    padding: 1.5rem;
}

#datePickerModal .calendar-grid table {
    margin-bottom: 0;
}

#datePickerModal .calendar-grid th,
#datePickerModal .calendar-grid td {
    text-align: center;
    vertical-align: middle;
    width: 14.28%;
}

/* Date input field styling */
.date-input-wrapper input {
    border-radius: 0.375rem;
    transition: border-color 0.15s ease-in-out, box-shadow 0.15s ease-in-out;
}

.date-input-wrapper input:focus {
    outline: 0;
    border-color: #86b7fe;
    box-shadow: 0 0 0 0.25rem rgba(13, 110, 253, 0.25);
}

.date-input-wrapper input.is-invalid {
    border-color: #dc3545;
    box-shadow: 0 0 0 0.25rem rgba(220, 53, 69, 0.25);
}

