        .file-upload-area:hover {
            border-color: #4f46e5;
            background: #f8fafc;
        }

        .file-upload-area.dragover {
            border-color: #4f46e5;
            background: #eff6ff;
        }

        @media (max-width: 768px) {
            .form-grid {
                grid-template-columns: 1fr;
                gap: 1.5rem;
            }

            .form-row {
                grid-template-columns: 1fr;
            }

            .form-actions {
                flex-direction: column;
                gap: 1rem;
            }

            .form-body {
                padding: 1.5rem;
            }

            .form-header {
                padding: 1.5rem;
            }

            .form-header h1 {
