// Main JavaScript for Cheque Management System

$(document).ready(function() {
    // Initialize tooltips
    const tooltipTriggerList = document.querySelectorAll('[data-bs-toggle="tooltip"]');
    const tooltipList = [...tooltipTriggerList].map(tooltipTriggerEl => new bootstrap.Tooltip(tooltipTriggerEl));

    // Auto-hide alerts after 5 seconds
    setTimeout(function() {
        $('.alert:not(.alert-permanent)').fadeOut('slow');
    }, 5000);

    // Confirm delete actions
    $('.btn-delete, .btn-danger[data-bs-toggle="modal"]').click(function(e) {
        const message = $(this).data('confirm') || 'Êtes-vous sûr de vouloir supprimer cet élément ?';
        if (!$(this).data('bs-toggle')) {
            if (!confirm(message)) {
                e.preventDefault();
                return false;
            }
        }
    });

    // Form validation enhancements
    $('form').on('submit', function() {
        const submitBtn = $(this).find('button[type="submit"]');
        submitBtn.addClass('btn-loading').prop('disabled', true);

        // Re-enable button after 3 seconds to prevent permanent disable on validation errors
        setTimeout(function() {
            submitBtn.removeClass('btn-loading').prop('disabled', false);
        }, 3000);
    });

    // Format currency inputs
    $('input[step="0.01"]').on('input', function() {
        let value = $(this).val();
        // Remove any non-numeric characters except decimal point
        value = value.replace(/[^0-9.]/g, '');
        // Ensure only one decimal point
        const parts = value.split('.');
        if (parts.length > 2) {
            value = parts[0] + '.' + parts.slice(1).join('');
        }
        // Limit to 2 decimal places
        if (parts[1] && parts[1].length > 2) {
            value = parts[0] + '.' + parts[1].substring(0, 2);
        }
        $(this).val(value);
    });

    // Date input helpers and formatting
    $('.date-today').click(function() {
        const today = new Date();
        const day = String(today.getDate()).padStart(2, '0');
        const month = String(today.getMonth() + 1).padStart(2, '0');
        const year = today.getFullYear();
        const dateString = day + '/' + month + '/' + year;
        $($(this).data('target')).val(dateString);
    });

    // Auto-select today's date for specific fields
    function setTodayDate(selector) {
        const today = new Date();
        const day = String(today.getDate()).padStart(2, '0');
        const month = String(today.getMonth() + 1).padStart(2, '0');
        const year = today.getFullYear();
        const dateString = day + '/' + month + '/' + year;
        $(selector).val(dateString);
    }

    // Add date picker buttons to date fields
    function addDatePickerButtons() {
        $('.date-input, input[data-date-format="dd/mm/yyyy"]').each(function() {
            const $input = $(this);
            const $wrapper = $('<div class="date-input-wrapper position-relative"></div>');

            // Wrap the input
            $input.wrap($wrapper);

            // Add quick date buttons
            const $buttonGroup = $('<div class="date-quick-buttons position-absolute end-0 top-0 h-100 d-flex align-items-center pe-2"></div>');
            const $todayBtn = $('<button type="button" class="btn btn-sm btn-outline-primary me-1" title="Aujourd\'hui">Auj.</button>');
            const $calendarBtn = $('<button type="button" class="btn btn-sm btn-outline-secondary" title="Calendrier"><i class="fas fa-calendar"></i></button>');

            $todayBtn.click(function(e) {
                e.preventDefault();
                setTodayDate($input);
                $input.trigger('blur'); // Trigger validation
            });

            $calendarBtn.click(function(e) {
                e.preventDefault();
                showDatePicker($input);
            });

            $buttonGroup.append($todayBtn, $calendarBtn);
            $input.parent().append($buttonGroup);

            // Adjust input padding to make room for buttons
            $input.css('padding-right', '90px');
        });
    }

    // Simple date picker modal
    function showDatePicker($input) {
        const today = new Date();
        const currentMonth = today.getMonth();
        const currentYear = today.getFullYear();

        // Create modal HTML
        const modalHTML = `
            <div class="modal fade" id="datePickerModal" tabindex="-1">
                <div class="modal-dialog modal-sm">
                    <div class="modal-content">
                        <div class="modal-header">
                            <h5 class="modal-title">Choisir une date</h5>
                            <button type="button" class="btn-close" data-bs-dismiss="modal"></button>
                        </div>
                        <div class="modal-body">
                            <div class="row mb-3">
                                <div class="col">
                                    <select class="form-select" id="monthSelect">
                                        <option value="0" ${currentMonth === 0 ? 'selected' : ''}>Janvier</option>
                                        <option value="1" ${currentMonth === 1 ? 'selected' : ''}>Février</option>
                                        <option value="2" ${currentMonth === 2 ? 'selected' : ''}>Mars</option>
                                        <option value="3" ${currentMonth === 3 ? 'selected' : ''}>Avril</option>
                                        <option value="4" ${currentMonth === 4 ? 'selected' : ''}>Mai</option>
                                        <option value="5" ${currentMonth === 5 ? 'selected' : ''}>Juin</option>
                                        <option value="6" ${currentMonth === 6 ? 'selected' : ''}>Juillet</option>
                                        <option value="7" ${currentMonth === 7 ? 'selected' : ''}>Août</option>
                                        <option value="8" ${currentMonth === 8 ? 'selected' : ''}>Septembre</option>
                                        <option value="9" ${currentMonth === 9 ? 'selected' : ''}>Octobre</option>
                                        <option value="10" ${currentMonth === 10 ? 'selected' : ''}>Novembre</option>
                                        <option value="11" ${currentMonth === 11 ? 'selected' : ''}>Décembre</option>
                                    </select>
                                </div>
                                <div class="col">
                                    <select class="form-select" id="yearSelect">
                                        ${generateYearOptions(currentYear)}
                                    </select>
                                </div>
                            </div>
                            <div class="quick-dates mb-3">
                                <button type="button" class="btn btn-sm btn-outline-primary me-2 quick-date" data-offset="0">Aujourd'hui</button>
                                <button type="button" class="btn btn-sm btn-outline-secondary me-2 quick-date" data-offset="1">Demain</button>
                                <button type="button" class="btn btn-sm btn-outline-secondary me-2 quick-date" data-offset="7">+7 jours</button>
                                <button type="button" class="btn btn-sm btn-outline-secondary quick-date" data-offset="30">+30 jours</button>
                            </div>
                            <div id="calendarGrid" class="calendar-grid"></div>
                        </div>
                    </div>
                </div>
            </div>
        `;

        // Remove existing modal if any
        $('#datePickerModal').remove();

        // Add modal to body
        $('body').append(modalHTML);

        // Generate calendar
        generateCalendar(currentMonth, currentYear);

        // Event handlers
        $('#monthSelect, #yearSelect').change(function() {
            const month = parseInt($('#monthSelect').val());
            const year = parseInt($('#yearSelect').val());
            generateCalendar(month, year);
        });

        $('.quick-date').click(function() {
            const offset = parseInt($(this).data('offset'));
            const date = new Date();
            date.setDate(date.getDate() + offset);
            setDateValue($input, date);
            $('#datePickerModal').modal('hide');
        });

        // Show modal
        $('#datePickerModal').modal('show');
    }

    function generateYearOptions(currentYear) {
        let options = '';
        for (let year = currentYear - 5; year <= currentYear + 10; year++) {
            options += `<option value="${year}" ${year === currentYear ? 'selected' : ''}>${year}</option>`;
        }
        return options;
    }

    function generateCalendar(month, year) {
        const firstDay = new Date(year, month, 1);
        const lastDay = new Date(year, month + 1, 0);
        const startDate = new Date(firstDay);
        startDate.setDate(startDate.getDate() - firstDay.getDay());

        let calendarHTML = '<div class="calendar-grid-container"><table class="table table-sm"><thead><tr>';
        const dayNames = ['Dim', 'Lun', 'Mar', 'Mer', 'Jeu', 'Ven', 'Sam'];
        dayNames.forEach(day => {
            calendarHTML += `<th class="text-center">${day}</th>`;
        });
        calendarHTML += '</tr></thead><tbody>';

        const currentDate = startDate;
        for (let week = 0; week < 6; week++) {
            calendarHTML += '<tr>';
            for (let day = 0; day < 7; day++) {
                const isCurrentMonth = currentDate.getMonth() === month;
                const isToday = currentDate.toDateString() === new Date().toDateString();
                const classes = `text-center calendar-day ${isCurrentMonth ? 'current-month' : 'other-month'} ${isToday ? 'today' : ''}`;

                calendarHTML += `<td class="${classes}" data-date="${currentDate.getFullYear()}-${String(currentDate.getMonth()).padStart(2, '0')}-${String(currentDate.getDate()).padStart(2, '0')}">${currentDate.getDate()}</td>`;
                currentDate.setDate(currentDate.getDate() + 1);
            }
            calendarHTML += '</tr>';

            if (currentDate.getMonth() !== month && week >= 4) break;
        }

        calendarHTML += '</tbody></table></div>';
        $('#calendarGrid').html(calendarHTML);

        // Add click handlers for calendar days
        $('.calendar-day.current-month').click(function() {
            const dateStr = $(this).data('date');
            const date = new Date(dateStr);
            setDateValue($('.date-input:focus, input[data-date-format="dd/mm/yyyy"]:focus').last(), date);
            $('#datePickerModal').modal('hide');
        });
    }

    function setDateValue($input, date) {
        const day = String(date.getDate()).padStart(2, '0');
        const month = String(date.getMonth() + 1).padStart(2, '0');
        const year = date.getFullYear();
        const dateString = day + '/' + month + '/' + year;
        $input.val(dateString);
        $input.trigger('blur');
    }

    // Format date inputs to dd/mm/yyyy
    function formatDateInput(element) {
        let value = element.val();
        if (value && value.match(/^\d{4}-\d{2}-\d{2}$/)) {
            // Convert yyyy-mm-dd to dd/mm/yyyy
            const parts = value.split('-');
            element.val(parts[2] + '/' + parts[1] + '/' + parts[0]);
        }
    }

    // Initialize date formatting for existing fields
    $('.date-input, input[data-date-format="dd/mm/yyyy"]').each(function() {
        const $this = $(this);

        // Set placeholder and attributes
        $this.attr('placeholder', 'dd/mm/yyyy');
        $this.attr('type', 'text');
        $this.attr('pattern', '\\d{2}/\\d{2}/\\d{4}');
        $this.attr('title', 'Format: dd/mm/yyyy');

        // Handle input formatting with better validation
        $this.on('input', function() {
            let value = $this.val();
            // Remove any non-numeric characters except forward slash
            value = value.replace(/[^\d\/]/g, '');

            // Auto-add slashes as user types
            if (value.length === 2 && !value.includes('/')) {
                value += '/';
            } else if (value.length === 5 && value.split('/').length === 2) {
                value += '/';
            }

            // Limit to dd/mm/yyyy format
            if (value.length > 10) {
                value = value.substring(0, 10);
            }

            $this.val(value);
        });

        $this.on('blur', function() {
            let value = $this.val();
            if (value) {
                // Validate and format dd/mm/yyyy
                const match = value.match(/^(\d{1,2})\/(\d{1,2})\/(\d{4})$/);
                if (match) {
                    const day = String(parseInt(match[1])).padStart(2, '0');
                    const month = String(parseInt(match[2])).padStart(2, '0');
                    const year = match[3];

                    // Validate date
                    const date = new Date(year, month - 1, day);
                    if (date.getFullYear() == year && 
                        date.getMonth() == month - 1 && 
                        date.getDate() == day) {
                        $this.val(day + '/' + month + '/' + year);
                        $this.removeClass('is-invalid');
                    } else {
                        $this.addClass('is-invalid');
                    }
                } else if (value.length > 0) {
                    $this.addClass('is-invalid');
                }
            } else {
                $this.removeClass('is-invalid');
            }
        });

        // Format existing values on page load
        formatDateInput($this);
    });

    // Initialize date picker buttons after DOM is ready
    setTimeout(addDatePickerButtons, 100);

    // Auto-select today's date for new cheque emission_date
    if (window.location.pathname.includes('/cheques/new') || window.location.pathname.includes('/cheques/create')) {
        setTimeout(function() {
            const emissionDateField = $('#emission_date');
            if (emissionDateField.length && !emissionDateField.val()) {
                setTodayDate(emissionDateField);
                emissionDateField.addClass('auto-date-selected');
            }
        }, 200);
    }

    // Status change confirmation
    $('.dropdown-item[data-status]').click(function(e) {
        const newStatus = $(this).data('status');
        const statusText = $(this).text();

        if (!confirm(`Changer le statut vers "${statusText}" ?`)) {
            e.preventDefault();
            return false;
        }
    });

    // Search form auto-submit delay
    let searchTimeout;
    $('input[name="search"]').on('input', function() {
        clearTimeout(searchTimeout);
        const form = $(this).closest('form');

        searchTimeout = setTimeout(function() {
            if (form.find('input[name="search"]').val().length >= 3 || form.find('input[name="search"]').val().length === 0) {
                form.submit();
            }
        }, 500);
    });

    // File upload preview
    $('input[type="file"]').change(function() {
        const file = this.files[0];
        const preview = $(this).siblings('.file-preview');

        if (file) {
            const fileName = file.name;
            const fileSize = (file.size / 1024 / 1024).toFixed(2); // Size in MB

            if (preview.length === 0) {
                $(this).after(`
                    <div class="file-preview mt-2">
                        <small class="text-muted">
                            <i class="fas fa-file me-1"></i>
                            <span class="file-name">${fileName}</span>
                            <span class="file-size">(${fileSize} MB)</span>
                        </small>
                    </div>
                `);
            } else {
                preview.find('.file-name').text(fileName);
                preview.find('.file-size').text(`(${fileSize} MB)`);
            }

            // Validate file size (16MB limit)
            if (file.size > 16 * 1024 * 1024) {
                alert('Le fichier est trop volumineux. Taille maximale: 16MB');
                $(this).val('');
                preview.remove();
            }
        } else {
            preview.remove();
        }
    });

    // Dynamic form field updates
    $('.client-type-radio').change(function() {
        updateClientFormFields();
    });

    function updateClientFormFields() {
        const selectedType = $('input[name="type"]:checked').val();

        if (selectedType === 'personne') {
            $('#nameLabel').text('Nom et prénom');
            $('#clientNameLabel').text('Nom et prénom');
            $('#clientIdLabel').text('CIN');
            $('#clientVatLabel').text('IF');
            $('.id-number-label').text('CIN (Carte d\'Identité Nationale)');
            $('.vat-number-label').text('IF (Identifiant Fiscal)');
        } else if (selectedType === 'entreprise') {
            $('#nameLabel').text('Raison sociale');
            $('#clientNameLabel').text('Raison sociale');
            $('#clientIdLabel').text('RC');
            $('#clientVatLabel').text('ICE');
            $('.id-number-label').text('RC (Registre de Commerce)');
            $('.vat-number-label').text('ICE (Identifiant Commun de l\'Entreprise)');
        }
    }

    // Initialize on page load
    updateClientFormFields();

    // Numeric input formatting
    $('.currency-input').on('input', function() {
        formatCurrency(this);
    });

    function formatCurrency(input) {
        let value = $(input).val().replace(/[^\d.]/g, '');
        let parts = value.split('.');

        // Format the integer part with thousands separators
        parts[0] = parts[0].replace(/\B(?=(\d{3})+(?!\d))/g, ',');

        // Limit decimal places to 2
        if (parts[1]) {
            parts[1] = parts[1].substring(0, 2);
        }

        $(input).val(parts.join('.'));
    }

    // Copy to clipboard functionality
    $('.copy-to-clipboard').click(function() {
        const text = $(this).data('text') || $(this).text();

        if (navigator.clipboard) {
            navigator.clipboard.writeText(text).then(function() {
                showToast('Copié dans le presse-papiers', 'success');
            });
        } else {
            // Fallback for older browsers
            const textArea = document.createElement('textarea');
            textArea.value = text;
            document.body.appendChild(textArea);
            textArea.select();
            document.execCommand('copy');
            document.body.removeChild(textArea);
            showToast('Copié dans le presse-papiers', 'success');
        }
    });

    // Show toast notifications
    function showToast(message, type = 'info') {
        const toast = $(`
            <div class="toast align-items-center text-white bg-${type} border-0" role="alert">
                <div class="d-flex">
                    <div class="toast-body">
                        ${message}
                    </div>
                    <button type="button" class="btn-close btn-close-white me-2 m-auto" data-bs-dismiss="toast"></button>
                </div>
            </div>
        `);

        if ($('.toast-container').length === 0) {
            $('body').append('<div class="toast-container position-fixed bottom-0 end-0 p-3"></div>');
        }

        $('.toast-container').append(toast);
        const bsToast = new bootstrap.Toast(toast[0]);
        bsToast.show();

        // Remove from DOM after hiding
        toast.on('hidden.bs.toast', function() {
            $(this).remove();
        });
    }

    // Print functionality
    $('.btn-print').click(function() {
        window.print();
    });

    // Export form validation
    $('form[action*="export"]').on('submit', function(e) {
        const dateFrom = $(this).find('input[name="date_from"]').val();
        const dateTo = $(this).find('input[name="date_to"]').val();

        if (dateFrom && dateTo && new Date(dateFrom) > new Date(dateTo)) {
            e.preventDefault();
            alert('La date de début doit être antérieure à la date de fin.');
            return false;
        }

        const submitBtn = $(this).find('button[type="submit"]');
        submitBtn.addClass('btn-loading').prop('disabled', true);

        // Show loading message
        showToast('Génération en cours...', 'info');

        // Re-enable button after 10 seconds for exports
        setTimeout(function() {
            submitBtn.removeClass('btn-loading').prop('disabled', false);
        }, 10000);
    });

    // Auto-refresh for dashboard (every 5 minutes)
    if (window.location.pathname === '/' || window.location.pathname.includes('dashboard')) {
        setInterval(function() {
            if (document.visibilityState === 'visible') {
                // Only refresh if page is visible
                window.location.reload();
            }
        }, 5 * 60 * 1000); // 5 minutes
    }

    // Keyboard shortcuts
    $(document).keydown(function(e) {
        // Ctrl+N for new entries
        if (e.ctrlKey && e.keyCode === 78) {
            e.preventDefault();
            const newButton = $('.btn-primary[href*="new"]').first();
            if (newButton.length) {
                window.location.href = newButton.attr('href');
            }
        }

        // Escape to close modals
        if (e.keyCode === 27) {
            $('.modal.show').modal('hide');
        }
    });

    // Smooth scrolling for anchor links
    $('a[href^="#"]').click(function(e) {
        e.preventDefault();
        const target = $($(this).attr('href'));

        if (target.length) {
            $('html, body').animate({
                scrollTop: target.offset().top - 70
            }, 500);
        }
    });

    // Table row click to edit (if data-edit-url is present)
    $('tr[data-edit-url]').click(function() {
        window.location.href = $(this).data('edit-url');
    });

    // Initialize any other components
    initializeComponents();
});

// Initialize additional components
function initializeComponents() {
    // Initialize any date pickers if using a library
    if (typeof flatpickr !== 'undefined') {
        flatpickr('input[type="date"]', {
            dateFormat: 'Y-m-d',
            locale: 'fr'
        });
    }

    // Initialize any other third-party components
    if (typeof Choices !== 'undefined') {
        const selects = document.querySelectorAll('select.form-select');
        selects.forEach(select => {
            new Choices(select, {
                searchEnabled: false,
                itemSelectText: '',
            });
        });
    }
}

// Utility functions
window.ChequeManager = {
    formatCurrency: function(amount, currency = 'MAD') {
        return new Intl.NumberFormat('fr-FR', {
            style: 'currency',
            currency: currency,
            minimumFractionDigits: 2
        }).format(amount);
    },

    formatDate: function(date) {
        return new Intl.DateTimeFormat('fr-FR').format(new Date(date));
    },

    showConfirm: function(message, callback) {
        if (confirm(message)) {
            callback();
        }
    },

    showAlert: function(message, type = 'info') {
        const alertDiv = $(`
            <div class="alert alert-${type} alert-dismissible fade show" role="alert">
                ${message}
                <button type="button" class="btn-close" data-bs-dismiss="alert"></button>
            </div>
        `);

        $('.container').first().prepend(alertDiv);

        // Auto-hide after 5 seconds
        setTimeout(function() {
            alertDiv.fadeOut();
        }, 5000);
    }
};

